""" Script d'entrée unique pour lancer l'ingestion et l'application des corporate actions (équivalent à 'python -m corporate_actions run'). """ from corporate_actions.cli import _run_all, _build_parser import logging import sys
def main(): logging.basicConfig( level=logging.INFO, format="%(asctime)s %(levelname)-8s %(name)s -- %(message)s", ) parser = _build_parser() args = parser.parse_args() # Force la commande 'run' même si non précisée if not hasattr(args, 'command') or args.command != 'run': args.command = 'run' _run_all(args)
if __name__ == "__main__": main()

import argparse import json import logging from datetime import datetime, timezone from uuid import uuid4
import dateutil.parser
from common.utils import configure_root_logging from event_sentiment.config import EventSentimentConfig from event_sentiment.db_io import EventSentimentRepository from event_sentiment.pipeline import EventSentimentPipeline
RUN_SUMMARY_PREFIX = "::alpha_trade_run_summary::"
def _utc_now_naive() -> datetime: return datetime.now(timezone.utc).replace(tzinfo=None)
def _build_run_id(prefix: str) -> str: return f"{prefix}-{_utc_now_naive().strftime('%Y%m%d%H%M%S')}-{uuid4().hex[:6]}"
def _emit_run_summary(summary: dict[str, object]) -> None: print( f"{RUN_SUMMARY_PREFIX}{json.dumps(summary, ensure_ascii=False, sort_keys=True, default=str)}", flush=True, )
def _build_cli_run_summary( *, stats: dict[str, object], started_at: datetime, finished_at: datetime, ) -> dict[str, object]: ingestion = stats.get("ingestion") if isinstance(stats.get("ingestion"), dict) else {} return { "run_id": _build_run_id("event-sentiment"), "started_at": started_at.isoformat(timespec="seconds"), "finished_at": finished_at.isoformat(timespec="seconds"), "duration_seconds": round((finished_at - started_at).total_seconds(), 2), "resolved_symbols": int(stats.get("resolved_symbols") or 0), "window_start_utc": stats.get("start_utc"), "window_end_utc": stats.get("end_utc"), "fetched_articles": int(ingestion.get("fetched") or 0), "deduped_articles": int(ingestion.get("deduped") or 0), "landed_articles": int(ingestion.get("landed") or 0), "ticker_maps": int(ingestion.get("ticker_maps") or 0), "sentiment_inferred": int(stats.get("sentiment_inferred") or 0), "macro_rows": int(stats.get("macro_rows") or 0), "ticker_day_rows": int(stats.get("ticker_day_rows") or 0), "sector_day_rows": int(stats.get("sector_day_rows") or 0), }
def build_arg_parser() -> argparse.ArgumentParser: parser = argparse.ArgumentParser(description="Pipeline Event Sentiment basée sur FinBERT") parser.add_argument("--start-utc", type=str, default=None, help="Fenêtre UTC de début, ex: 2026-01-01T00:00:00Z") parser.add_argument("--end-utc", type=str, default=None, help="Fenêtre UTC de fin, ex: 2026-01-31T23:59:59Z") parser.add_argument("--symbols", type=str, default=None, help="Liste optionnelle de symboles, séparés par des virgules") return parser
def main() -> None: configure_root_logging( level=logging.INFO, log_path="./log/event_sentiment.log", fmt="%(asctime)s %(levelname)s %(message)s", ) args = build_arg_parser().parse_args()
start_utc = dateutil.parser.isoparse(args.start_utc) if args.start_utc else None end_utc = dateutil.parser.isoparse(args.end_utc) if args.end_utc else None symbols = [symbol.strip().upper() for symbol in args.symbols.split(",")] if args.symbols else None
repository = EventSentimentRepository() config = EventSentimentConfig() pipeline = EventSentimentPipeline(repository=repository, config=config) started_at = _utc_now_naive() stats = pipeline.run(start_utc=start_utc, end_utc=end_utc, symbols=symbols) finished_at = _utc_now_naive() _emit_run_summary( _build_cli_run_summary( stats=stats, started_at=started_at, finished_at=finished_at, ) )

# IHM Opérateur — Alpha Trade

Dashboard de supervision Streamlit pour le pipeline de trading algorithmique Alpha Trade.

## Prérequis

- Python ≥ 3.12
- Variables d'environnement MySQL optionnelles : `LOGIN_DB`, `PASSWORD_DB`
- MySQL démarré avec la base `alpha_trade`
- Dépendances installées : `pip install -r requirements.txt`

## Lancement

```powershell
python -m streamlit run ihm/app.py
```

L'application s'ouvre par défaut sur `http://localhost:8501`.

## Connexion base de données

L'IHM peut maintenant se connecter à MySQL de deux façons :

1. via les variables d'environnement `LOGIN_DB` / `PASSWORD_DB` ;
2. via le formulaire **️ Connexion DB** disponible dans la sidebar et dans la page **⚙️ Paramètres / Santé**.

Vous pouvez y renseigner :

- l'hôte MySQL ;
- le nom de la base ;
- le login ;
- le mot de passe.

Cela évite que les pages `Execution`, `Corporate Actions`, `ML`, etc. paraissent vides quand les identifiants système ne sont pas définis.

## Structure des pages

| Page | Description |
|---|---|
|  Vue d'ensemble | KPI, alertes, top candidats, santé DB |
|  Pipeline | Workflow quotidien 1→14 + steps auxiliaires Data Integrity (`import_alpaca_assets`, `update_sector`), lancement en arrière-plan, arrêt, historique, comparaison, téléchargement des logs et résumés métier |
|  Backtesting | Formulaire complet des commandes `backtesting run`, `backfill-scores-history`, `diagnose-screener` et `recommend-screener`, lancement en arrière-plan, logs centralisés, KPIs auto-rafraîchis et graphique live des artefacts |
|  Screening | Table `stock_scores` avec filtres (symbole, secteur, candidat, score, sentiment) + lecture directe des recommandations screener par objectif (robuste, offensif, bear, exécutable) |
| ⚖️ Risk | Décisions de risque, portefeuille cible, synthèse par secteur |
|  Execution | Runs d'exécution, événements, fills, positions broker |
|  Corporate Actions | Événements CA, applications, dividendes cumulés |
|  ML / Prédictions | Runs training, métriques, prédictions LSTM |
| ⚙️ Paramètres / Santé | Variables d'env, connexion DB, dépendances, version Python |

## Pilotage des pipelines

La page ** Pipeline** permet désormais :

- de lancer le **workflow quotidien complet 1→14** dans l'ordre métier ;
- de lancer aussi des steps **hors workflow** pour le bootstrap / la maintenance Data Integrity ;
- de lancer une étape **en arrière-plan** sans bloquer la navigation dans l'IHM ;
- d'**arrêter** un run actif lancé depuis l'interface ;
- de consulter un **historique centralisé** des exécutions IHM ;
- de comparer deux runs et leurs logs ;
- de filtrer l'affichage des logs par **`stdout` / `stderr` / `tout`** ;
- de **télécharger** les fichiers de logs produits par chaque run.

Le bloc de paramètres expose aussi les options réellement supportées côté backend pour :

- `Alpha Scanner` (`chunk-size`, `selection-size`, `max-workers`, seuils stricts de liquidité/prix/RS/ATR/spread/earnings, `sector-cap-ratio`, `log-level`) ;
- `event_sentiment` (`start-utc`, `end-utc`, `symbols`) ;
- `signal_aggregator` (`trade-date`, `all-symbols`, `sentiment-weight`, `macro-weight`, `lookback-days`, `min-news-count`, `time-decay-half-life-days`, `log-level`) ;
- `sync_latest_quotes` (`limit`, `batch-size`) ;
- `sync_earnings_calendar` (`from-date`, `to-date`, `limit`, `sleep-seconds`) ;
- `update_sector` (`limit`, `sleep-seconds`, `log-every`).

Pour `Alpha Scanner`, l'IHM transmet explicitement les valeurs affichées au launcher `python -m selector.alpha_scanner ...` afin de reproduire le profil partagé strict `STRICT_SWING_CASH_FILTERS` ou de le surcharger proprement. Dans cette UI, `0` sur `max workers` signifie **auto**.

Pour `event_sentiment`, laisser les symboles vides signifie : reprendre automatiquement l'univers candidat `stock_scores.is_candidate = 1`. Pour `signal_aggregator`, la page réutilise le champ global `trade date` quand il est renseigné et calcule le poids quantitatif implicite `1 - sentiment_weight - macro_weight` comme le backend.

La carte `Alpha Scanner` inclut également un diagnostic de dépendances métier pour `stock_quote_snapshots` et `stock_earnings_calendar` :

- badge visuel par step de sync ;
- métriques `latest_date`, `% couverture`, `N symboles` ;
- seuils vert / orange / rouge éditables depuis la page `⚙️ Paramètres / Santé` (et toujours accessibles depuis ` Pipeline`) ;
- presets applicables en un clic : `Swing Cash Pro`, `Agressif`, `Tolérant` ;
- croisement explicite `style opératoire × régime de marché` (`normal`, `faible`, `très sélectif`) ;
- expander expliquant les états rouge/orange ;
- commandes correctives et boutons d'action rapide pour relancer les deux syncs ;
- bouton `Alpha Scanner` réellement désactivé quand **les deux** dépendances sont rouges ;
- message post-succès rappelant que le cache IHM peut nécessiter ~60s, avec option `Rafraîchir maintenant`.

Le même diagnostic est aussi affiché en **lecture seule** dans les pages ** Vue d'ensemble** et ** Screening** pour rendre immédiatement visible l'état des dépendances du scan strict.

Les valeurs par défaut proposées sont orientées **swing cash pro** :

- `Sync Latest Quotes` : orange si couverture < `85%`, rouge si < `60%`, orange si snapshot > `1` jour, rouge si > `3` jours ;
- `Sync Earnings Calendar` : orange si couverture < `15%`, rouge si < `5%`, orange si horizon futur < `14` jours, rouge si < `7` jours.

La page `⚙️ Paramètres / Santé` permet aussi d'appliquer un preset selon **deux axes simultanés** :

- **style opératoire** : `Swing Cash Pro` / `Agressif` / `Tolérant` ;
- **régime de marché** : `Marché normal` / `Marché faible` / `Marché très sélectif`.

Exemple : `Agressif × Marché faible` ou `Swing Cash Pro × Marché très sélectif`.

Quand un script écrit un résumé structuré préfixé par `::alpha_trade_run_summary::`, l'IHM l'extrait automatiquement pour alimenter :

- les cartes de résumé métier du run ;
- l'agrégation du workflow parent ;
- les blocs récents de `Overview` et `Screening`.

Cela couvre notamment `stock_screener` et `Alpha Scanner`, ce qui permet d'afficher côté IHM des métriques comme la taille de sélection demandée, le nombre de titres retenus, le nombre de secteurs couverts, le fill ratio ou encore le cap sectoriel utilisé.

Cela couvre aussi `event_sentiment` et `signal_aggregator`, avec des métriques comme le nombre de symboles résolus, les articles fetchés/landed, les lignes de features journalières générées, le nombre de symboles mis à jour par la fusion sentiment ou encore le score sentiment moyen/max agrégé.

Les logs IHM sont persistés sous `artifacts/ihm_pipeline_runs/`.

Les runs de backtesting lancés depuis l'IHM sont persistés sous `artifacts/ihm_backtesting_runs/`.

## Recommandations screener côté dashboard

Quand les artefacts suivants existent dans `artifacts/screener_diagnostics/` :

- `scenario_recommendations_by_objective.csv`
- `recommendation_summary_by_objective.json`
- `metadata.json`

l'IHM expose automatiquement :

- un **résumé compact** sur la page ** Vue d'ensemble** ;
- un **bloc détaillé** sur la page ** Screening** avec les leaders par objectif et le leaderboard phase 7.

Cette phase 8 ne relance pas le diagnostic depuis l'interface :
elle **lit les artefacts existants** produits par `python -m backtesting diagnose-screener` ou `python -m backtesting recommend-screener`.

## Lancement screener depuis l'IHM

La page ** Pipeline** expose désormais aussi l'étape quotidienne `stock_screener` avec les options backend réellement disponibles (`chunk-size`, `max-workers`, `benchmark`, seuils de liquidité/RS/range, fenêtre de passe 1, mode 2 passes).

En complément, la page ** Backtesting** permet aussi de lancer directement depuis Streamlit :

- `python -m backtesting diagnose-screener`
- `python -m backtesting recommend-screener`

Chaque lancement :

- s'exécute en arrière-plan ;
- alimente le même centre de logs/historique que les autres runs backtesting ;
- peut réécrire les artefacts sous `artifacts/screener_diagnostics/` pour rafraîchir automatiquement la page ** Screening**.

## Limitations connues

- **Pilotage encadré** : la page Pipeline peut lancer/arrêter des sous-processus, mais les autres pages restent orientées supervision
- Si la DB est indisponible, les pages affichent un diagnostic clair et un formulaire de connexion
- Si une table SQL n'existe pas encore, la page correspondante affiche un message indiquant un schéma ou une migration manquante
- Le cache Streamlit est configuré à 60 secondes (TTL) sur les requêtes DB

"""Composants réutilisables pour le diagnostic de dépendances Alpha Scanner."""
from __future__ import annotations

from typing import cast

import pandas as pd
import streamlit as st

from ihm.components.status_badges import badge


DependencyDiagnostic = dict[str, object]


def dependency_badge(status: str, label: str) -> str:
    status_map = {"green": "ok", "orange": "warn", "red": "error"}
    status_label = {"green": "OK", "orange": "À surveiller", "red": "Bloquant"}.get(status, "Inconnu")
    return badge(f"{label} · {status_label}", status_map.get(status, "info"))


def get_dependency_payload(diagnostic: DependencyDiagnostic | None, step_key: str) -> dict[str, object] | None:
    if not isinstance(diagnostic, dict):
        return None
    dependencies = diagnostic.get("dependencies")
    if not isinstance(dependencies, dict):
        return None
    payload = dependencies.get(step_key)
    return payload if isinstance(payload, dict) else None


def format_dependency_latest_date(value: object) -> str:
    text_value = str(value or "").strip()
    return text_value or "—"


def format_dependency_symbol_count(value: object) -> str:
    try:
        return f"{int(str(value))}"
    except (TypeError, ValueError):
        return "0"


def build_alpha_scanner_dependency_rows(diagnostic: DependencyDiagnostic | None) -> pd.DataFrame:
    if not isinstance(diagnostic, dict):
        return pd.DataFrame()
    dependencies = diagnostic.get("dependencies")
    if not isinstance(dependencies, dict) or not dependencies:
        return pd.DataFrame()

    rows: list[dict[str, object]] = []
    for payload in dependencies.values():
        if not isinstance(payload, dict):
            continue
        rows.append(
            {
                "Dépendance": dependency_badge(str(payload.get("status") or "red"), str(payload.get("label") or "dépendance")),
                "latest_date": format_dependency_latest_date(payload.get("latest_date")),
                "% couverture": f"{float(payload.get('coverage_pct') or 0.0):.1f}%",
                "N symboles": format_dependency_symbol_count(payload.get("covered_symbols")),
                "Univers": format_dependency_symbol_count(payload.get("eligible_symbols")),
                "Diagnostic": str(payload.get("reason") or "—"),
                "Commande": str(payload.get("command") or "—"),
            }
        )
    return pd.DataFrame(rows)


def render_dependency_metrics(payload: dict[str, object]) -> None:
    metric_col1, metric_col2, metric_col3 = st.columns(3)
    metric_col1.metric("latest_date", format_dependency_latest_date(payload.get("latest_date")))
    metric_col2.metric("% couverture", f"{float(payload.get('coverage_pct') or 0.0):.1f}%")
    metric_col3.metric("N symboles", format_dependency_symbol_count(payload.get("covered_symbols")))
    st.caption(
        f"Univers éligible de référence : `{format_dependency_symbol_count(payload.get('eligible_symbols'))}` symbole(s) | "
        f"table : `{payload.get('table')}`"
    )
    st.caption(str(payload.get("reason") or "Diagnostic indisponible."))


def render_alpha_scanner_dependency_panel(
    diagnostic: DependencyDiagnostic | None,
    *,
    title: str,
    expanded: bool = False,
    show_commands: bool = True,
) -> None:
    rows = build_alpha_scanner_dependency_rows(diagnostic)
    if rows.empty:
        return

    all_red = bool(diagnostic.get("all_red")) if isinstance(diagnostic, dict) else False
    any_red_or_orange = bool(diagnostic.get("any_red_or_orange")) if isinstance(diagnostic, dict) else False

    if all_red:
        st.error(
            "Alpha Scanner détecte deux dépendances rouges : les filtres `spread_bps` et `earnings_blackout` risquent d'être inexploitables."
        )
    elif any_red_or_orange:
        st.warning(
            "Alpha Scanner détecte une couverture partielle ou vieillissante sur ses dépendances quotes/earnings."
        )
    else:
        st.success("Dépendances Alpha Scanner OK : quotes et earnings sont alimentés pour les filtres stricts.")

    with st.expander(title, expanded=expanded):
        st.dataframe(rows, use_container_width=True, hide_index=True)
        if show_commands:
            quotes_payload = get_dependency_payload(diagnostic, "sync_latest_quotes")
            earnings_payload = get_dependency_payload(diagnostic, "sync_earnings_calendar")
            if quotes_payload or earnings_payload:
                cmd_col1, cmd_col2 = st.columns(2)
                if quotes_payload:
                    with cmd_col1:
                        st.code(str(quotes_payload.get("command") or "python -m dataIntegrityEngine.sync_latest_quotes"), language="powershell")
                if earnings_payload:
                    with cmd_col2:
                        st.code(str(earnings_payload.get("command") or "python -m dataIntegrityEngine.sync_earnings_calendar"), language="powershell")

"""Presets de seuils de diagnostic Alpha Scanner selon style opératoire et régime de marché."""
from __future__ import annotations

from copy import deepcopy
from typing import Literal

MarketRegime = Literal["normal", "weak", "very_selective"]
PresetStyle = Literal["swing_cash_pro", "aggressive", "tolerant"]

PRESET_STYLE_LABELS: dict[PresetStyle, str] = {
    "swing_cash_pro": "Swing Cash Pro",
    "aggressive": "Agressif",
    "tolerant": "Tolérant",
}

MARKET_REGIME_LABELS: dict[MarketRegime, str] = {
    "normal": "Marché normal",
    "weak": "Marché faible",
    "very_selective": "Marché très sélectif",
}

BASE_STYLE_THRESHOLDS: dict[PresetStyle, dict[str, dict[str, float]]] = {
    "swing_cash_pro": {
        "sync_latest_quotes": {
            "coverage_warn_pct": 85.0,
            "coverage_error_pct": 60.0,
            "max_age_warn_days": 1.0,
            "max_age_error_days": 3.0,
        },
        "sync_earnings_calendar": {
            "coverage_warn_pct": 15.0,
            "coverage_error_pct": 5.0,
            "min_horizon_warn_days": 14.0,
            "min_horizon_error_days": 7.0,
        },
    },
    "aggressive": {
        "sync_latest_quotes": {
            "coverage_warn_pct": 75.0,
            "coverage_error_pct": 45.0,
            "max_age_warn_days": 2.0,
            "max_age_error_days": 5.0,
        },
        "sync_earnings_calendar": {
            "coverage_warn_pct": 10.0,
            "coverage_error_pct": 3.0,
            "min_horizon_warn_days": 10.0,
            "min_horizon_error_days": 5.0,
        },
    },
    "tolerant": {
        "sync_latest_quotes": {
            "coverage_warn_pct": 65.0,
            "coverage_error_pct": 35.0,
            "max_age_warn_days": 3.0,
            "max_age_error_days": 7.0,
        },
        "sync_earnings_calendar": {
            "coverage_warn_pct": 7.0,
            "coverage_error_pct": 2.0,
            "min_horizon_warn_days": 7.0,
            "min_horizon_error_days": 3.0,
        },
    },
}

REGIME_ADJUSTMENTS: dict[MarketRegime, dict[str, dict[str, float]]] = {
    "normal": {
        "sync_latest_quotes": {
            "coverage_warn_pct": 0.0,
            "coverage_error_pct": 0.0,
            "max_age_warn_days": 0.0,
            "max_age_error_days": 0.0,
        },
        "sync_earnings_calendar": {
            "coverage_warn_pct": 0.0,
            "coverage_error_pct": 0.0,
            "min_horizon_warn_days": 0.0,
            "min_horizon_error_days": 0.0,
        },
    },
    "weak": {
        "sync_latest_quotes": {
            "coverage_warn_pct": 5.0,
            "coverage_error_pct": 5.0,
            "max_age_warn_days": -1.0,
            "max_age_error_days": -1.0,
        },
        "sync_earnings_calendar": {
            "coverage_warn_pct": 3.0,
            "coverage_error_pct": 2.0,
            "min_horizon_warn_days": 3.0,
            "min_horizon_error_days": 2.0,
        },
    },
    "very_selective": {
        "sync_latest_quotes": {
            "coverage_warn_pct": 10.0,
            "coverage_error_pct": 10.0,
            "max_age_warn_days": -1.0,
            "max_age_error_days": -2.0,
        },
        "sync_earnings_calendar": {
            "coverage_warn_pct": 5.0,
            "coverage_error_pct": 3.0,
            "min_horizon_warn_days": 7.0,
            "min_horizon_error_days": 3.0,
        },
    },
}


def _clamp_threshold(metric_key: str, value: float) -> float:
    if metric_key.endswith("_pct"):
        return max(0.0, min(value, 100.0))
    if metric_key.endswith("_days"):
        return max(0.0, value)
    return max(0.0, value)


def get_alpha_scanner_threshold_preset(
    *,
    style: PresetStyle,
    market_regime: MarketRegime,
) -> dict[str, dict[str, float]]:
    thresholds = deepcopy(BASE_STYLE_THRESHOLDS[style])
    adjustments = REGIME_ADJUSTMENTS[market_regime]
    for step_key, metrics in thresholds.items():
        for metric_key, metric_value in metrics.items():
            adjusted_value = metric_value + adjustments.get(step_key, {}).get(metric_key, 0.0)
            thresholds[step_key][metric_key] = float(_clamp_threshold(metric_key, adjusted_value))
    return thresholds


DEFAULT_PRESET_STYLE: PresetStyle = "swing_cash_pro"
DEFAULT_MARKET_REGIME: MarketRegime = "normal"
DEFAULT_ALPHA_SCANNER_DEPENDENCY_THRESHOLDS = get_alpha_scanner_threshold_preset(
    style=DEFAULT_PRESET_STYLE,
    market_regime=DEFAULT_MARKET_REGIME,
)

"""ihm/services/queries.py — Requêtes SQL centralisées pour l'IHM.""" from __future__ import annotations
import json
import pandas as pd import streamlit as st
from database.run_business_summaries import parse_summary_json from ihm.services.run_summary import build_run_summary_caption from ihm.services.db import safe_query, safe_scalar
# --------------------------------------------------------------------------- # Overview # ---------------------------------------------------------------------------
@st.cache_data(ttl=60, show_spinner=False) def get_candidates_count() -> int: v = safe_scalar("SELECT COUNT(*) FROM stock_scores WHERE is_candidate = 1") return int(v) if v is not None else 0
@st.cache_data(ttl=60, show_spinner=False) def get_top_candidates(n: int = 10) -> pd.DataFrame: return safe_query(f""" SELECT symbol, sector, final_score_sentiment, final_score, total_score, is_candidate FROM stock_scores WHERE is_candidate = 1 AND final_score_sentiment IS NOT NULL ORDER BY final_score_sentiment DESC LIMIT {n} """)
@st.cache_data(ttl=60, show_spinner=False) def get_latest_risk_run_id() -> str | None: v = safe_scalar("SELECT run_id FROM portfolio_targets ORDER BY created_at DESC LIMIT 1") return str(v) if v else None
@st.cache_data(ttl=60, show_spinner=False) def get_latest_exec_run() -> pd.DataFrame: return safe_query(""" SELECT exec_run_id, risk_run_id, trade_date, broker_mode, dry_run, status, started_at, completed_at, total_targets, total_submitted, total_filled, error_message FROM execution_runs ORDER BY started_at DESC LIMIT 1 """)
# --------------------------------------------------------------------------- # Screening # ---------------------------------------------------------------------------
@st.cache_data(ttl=60, show_spinner=False) def get_stock_scores() -> pd.DataFrame: return safe_query(""" SELECT symbol, sector, is_candidate, total_score, final_score, final_score_sentiment, trend_score, vcp_score, signal_active, total_news, anomaly_count, missing_days_count, last_updated_score, last_updated_scan, last_updated_sentiment FROM stock_scores ORDER BY final_score_sentiment DESC, total_score DESC """)
# --------------------------------------------------------------------------- # Risk # ---------------------------------------------------------------------------
@st.cache_data(ttl=60, show_spinner=False) def get_risk_run_ids() -> list[str]: df = safe_query("SELECT DISTINCT run_id FROM risk_decisions ORDER BY run_id DESC LIMIT 50") return df["run_id"].tolist() if not df.empty else []
@st.cache_data(ttl=60, show_spinner=False) def get_risk_decisions(run_id: str | None = None) -> pd.DataFrame: if run_id: return safe_query(""" SELECT * FROM risk_decisions WHERE run_id = :run_id ORDER BY created_at DESC """, {"run_id": run_id}) return safe_query("SELECT * FROM risk_decisions ORDER BY created_at DESC LIMIT 200")
