row = df.iloc[0] payload_raw = row.get("payload_json") payload: dict[str, object] = {} if isinstance(payload_raw, str) and payload_raw.strip(): try: parsed = json.loads(payload_raw) if isinstance(parsed, dict): payload = parsed except Exception: payload = {} payload.setdefault("message", row.get("message", "")) payload.setdefault("created_at", row.get("created_at")) return payload
